package com.disasterrelief.controller;
import java.util.List; import com.disasterrelief.dto.ResourceRequest; import com.disasterrelief.model.Resource; import com.disasterrelief.service.ReliefService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/resources") public class ResourceController { private final ReliefService s; public ResourceController(ReliefService s){this.s=s;} @GetMapping public List<Resource> all(){return s.resources();} @GetMapping("/{id}") public Resource one(@PathVariable Long id){return s.resource(id);} @PostMapping public ResponseEntity<Resource> create(@Valid @RequestBody ResourceRequest x){return ResponseEntity.status(HttpStatus.CREATED).body(s.saveResource(x,null));} @PutMapping("/{id}") public Resource update(@PathVariable Long id,@Valid @RequestBody ResourceRequest x){return s.saveResource(x,id);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.deleteResource(id);} }
